"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26303"],{5e4(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.tipo_processo_codigo_em_branco","status":422,"titulo":"O c\xf3digo do tipo de processo do modelo veio em branco"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.tipo_processo_codigo_em_branco","requisitos":[],"oQueAconteceu":["O `tipoProcessoCodigo` enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) est\xe1 presente, mas vazio ou s\xf3 com espa\xe7os. O campo \xe9 opcional: ausente ou `null`, o modelo serve a todos os tipos de processo. Um texto em branco seria gravado como ausente e mudaria o alcance do modelo sem que ningu\xe9m o pedisse, por isso \xe9 recusado.","A recusa vem na lista `errors` da resposta, com `field` igual a `tipoProcessoCodigo`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Para um modelo de um tipo de processo, informe o c\xf3digo do tipo. Para um modelo que serve a todos os tipos, omita o campo ou envie `null`."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);